"""Real, confirmed mainnet signature-verification fixtures.

GENERATED by build_bitcoin_safe_fixtures.py; no network calls during tests.
Parent transactions are embedded, and all prevouts are reconstructed from them.
"""

import bdkpython as bdk
import pytest

from bitcoin_safe.input_signature_verifier import InputVerdict, Prevout, verify_transaction

SPENDS = {
    "0088b05ec68ab6b8702d78ec09fed9f7fa5903f613d1ed4bd2e85f8052c37cc7": "",
    "04610968cc33b95617ea21327d549046cf1766a2f0735ad9e57d4d7ae72ba106": "",
    "081b7d86f28efac1be53502f72a629798089b84608e55435310ffdfbce97a382": "",
    "1f71213dfb043f5adec94bfa1e89e7465bfc8ac606cf07837fc17c7293e245c2": "",
    "375dccfdb6edad0988df07abddbdbdece409080230bc605c6cba589d038ea72a": "",
    "553e50ced2ef9fb44327ed2aefc620bae8e1e77d7fb84e47cdf507d5caac67bd": "",
}

PARENTS = {
    "6a67f241084ab8400aa86ab0c2339d2536662a11b62f650c694ba44bb6f3cb13": "",
    "915fb32ad8e1bd3ee197b38ad158ff74a7eb17f03d71c89f1061e35e471483d3": "",
    "a56820fc2c9352e602effa8217336f11393e75f134ca01f421363b87ca673a50": "",
    "bf921dd2fb54d3ed095363efa47c751fa109cb820940d2fe73a07b18afc01726": "",
    "f025542515afe479a5789b689675f41382ff60b1b36cc5b63758efdea6a816c0": "",
    "4897c452b07a736216c486f12ba56dce1ac3be98091711492a8dfcba11c1abdb": "0200000001ea6fcddf135b57eb5bdb3bec572b76f1318e733fea8692847cb83babf68961c80000000000fdffffff01ab1900000000000022002060342ed5f202c24ddae8785a902a00d9b73c5f9866d4a8d289ef549b752bf8d1cfdf0e00",
}

CASES = [
    (
        "0088b05ec68ab6b8702d78ec09fed9f7fa5903f613d1ed4bd2e85f8052c37cc7",
        ["P2PKH"],
        ["bf921dd2fb54d3ed095363efa47c751fa109cb820940d2fe73a07b18afc01726"],
    ),
    (
        "04610968cc33b95617ea21327d549046cf1766a2f0735ad9e57d4d7ae72ba106",
        ["P2WPKH"],
        ["a56820fc2c9352e602effa8217336f11393e75f134ca01f421363b87ca673a50"],
    ),
    (
        "081b7d86f28efac1be53502f72a629798089b84608e55435310ffdfbce97a382",
        ["P2SH-P2WPKH"],
        ["6a67f241084ab8400aa86ab0c2339d2536662a11b62f650c694ba44bb6f3cb13"],
    ),
    (
        "1f71213dfb043f5adec94bfa1e89e7465bfc8ac606cf07837fc17c7293e245c2",
        ["P2TR-keypath"],
        ["915fb32ad8e1bd3ee197b38ad158ff74a7eb17f03d71c89f1061e35e471483d3"],
    ),
    (
        "375dccfdb6edad0988df07abddbdbdece409080230bc605c6cba589d038ea72a",
        ["P2WSH-multisig"],
        ["f025542515afe479a5789b689675f41382ff60b1b36cc5b63758efdea6a816c0"],
    ),
    (
        "553e50ced2ef9fb44327ed2aefc620bae8e1e77d7fb84e47cdf507d5caac67bd",
        ["P2WSH-multisig"],
        ["4897c452b07a736216c486f12ba56dce1ac3be98091711492a8dfcba11c1abdb"],
    ),
]


@pytest.mark.parametrize("txid, kinds, parent_ids", CASES, ids=[x[0][:12] for x in CASES])
def test_confirmed_mainnet_signatures(txid, kinds, parent_ids):
    spend = bdk.Transaction(bytes.fromhex(SPENDS[txid]))
    assert str(spend.compute_txid()) == txid
    assert len(spend.input()) == len(parent_ids)

    prevouts = []
    for txin, parent_id in zip(spend.input(), parent_ids, strict=True):
        parent = bdk.Transaction(bytes.fromhex(PARENTS[parent_id]))
        assert str(parent.compute_txid()) == parent_id
        assert str(txin.previous_output.txid) == parent_id
        output = parent.output()[txin.previous_output.vout]
        prevouts.append(
            Prevout(
                script_pubkey=bytes(output.script_pubkey.to_bytes()),
                value=output.value.to_sat(),
            )
        )

    verdicts = verify_transaction(spend, prevouts, [True] * len(prevouts)).verdicts
    assert verdicts == [InputVerdict.valid] * len(prevouts), (kinds, verdicts)
